type application struct {
	ID                   string              `json:"id"`
	Version              string              `json:"version"`
	Enabled              bool                `json:"enabled"`
	Required             bool                `json:"required"`
	RoutePrefix          string              `json:"route_prefix"`
	Upstream             string              `json:"upstream"`
	ReadinessPath        string              `json:"readiness_path"`
	Audience             string              `json:"audience"`
	CapabilityNamespace  string              `json:"capability_namespace,omitempty"`
	CapabilityNamespaces []string            `json:"capability_namespaces,omitempty"`
	EntryAction          string              `json:"entry_action,omitempty"`
	EntryActions         []string            `json:"entry_actions,omitempty"`
	CapabilityManifest   string              `json:"capability_manifest,omitempty"`
	ShowInWorkbench      *bool               `json:"show_in_workbench,omitempty"`
	WorkItemProjection   *workItemProjection `json:"work_item_projection,omitempty"`
	MetricProjection     *metricProjection   `json:"metric_projection,omitempty"`
}
type workItemProjection struct {
	SchemaVersion string `json:"schema_version"`
	Path          string `json:"path"`
	Action        string `json:"action"`
}

var entryActionPattern = regexp.MustCompile(`^[a-z][a-z0-9-]*(\.[a-z][a-z0-9-]*)+$`)
var capabilityNamespacePattern = regexp.MustCompile(`^[a-z][a-z0-9-]{2,63}$`)
var canonicalUUIDPattern = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$`)

func (app application) hasEntry() bool {
	return app.EntryAction != "" || len(app.EntryActions) != 0
}

func (app application) validateEntry() error {
	platform := app.ID == "identity-access" || app.ID == "unified-workbench"
	if platform && (app.EntryAction != "" || app.EntryActions != nil) {
		return fmt.Errorf("platform application %q cannot declare entry capabilities", app.ID)
	}
	if app.CapabilityNamespace != "" && app.CapabilityNamespaces != nil {
		return fmt.Errorf("single and multiple capability namespaces are exclusive")
	}
	namespaces := app.CapabilityNamespaces
	if namespaces == nil {
		namespace := app.CapabilityNamespace
		if namespace == "" {
			namespace = app.Audience
		}
		if namespace == "" {
			namespace = app.ID
		}
		namespaces = []string{namespace}
	}
	if len(namespaces) == 0 || len(namespaces) > 16 {
		return fmt.Errorf("capability namespaces are invalid")
	}
	namespaceSet := map[string]bool{}
	for _, namespace := range namespaces {
		if !capabilityNamespacePattern.MatchString(namespace) || namespaceSet[namespace] {
			return fmt.Errorf("capability namespace is invalid or duplicate")
		}
		namespaceSet[namespace] = true
	}
	if app.EntryActions == nil {
		return nil // Preserve legacy navigation; Gateway owns full Manifest validation.
	}
	if app.EntryAction != "" || len(app.EntryActions) == 0 || len(app.EntryActions) > 16 {
		return fmt.Errorf("application %q entry capabilities are invalid", app.ID)
	}
	seen := map[string]bool{}
	for _, action := range app.EntryActions {
		matched := false
		for namespace := range namespaceSet {
			if strings.HasPrefix(action, namespace+".") {
				matched = true
				break
			}
		}
		if !entryActionPattern.MatchString(action) || !matched || seen[action] {
			return fmt.Errorf("application %q entry action is invalid", app.ID)
		}
		seen[action] = true
	}
	return nil
}

type metricProjection struct {
	SchemaVersion string `json:"schema_version"`
	Path          string `json:"path"`
	Action        string `json:"action"`
}
type suite struct {
	SchemaVersion string        `json:"schema_version"`
	SuiteID       string        `json:"suite_id"`
	TenantID      string        `json:"tenant_id"`
	Applications  []application `json:"applications"`
}
type Server struct {
	suite    suite
	page     *template.Template
	profiles ReferenceOAProfiles
}

// Explicit customer UI selection, not IAM authority or automatic enrollment.
type ReferenceOAProfiles struct {
	ProductionPersonnel string
	Bonus               string
	ProductionStage     string
	OMSOperatingPartyID string
}
