func presentationFor(id string) applicationPresentation {
	if value, ok := applicationPresentations[id]; ok {
		return value
	}
	return applicationPresentation{Title: id, Description: "进入已选装业务工作区", Glyph: "用", Section: "resource"}
}

func New(manifestPath string) (*Server, error) {
	return NewWithProfiles(manifestPath, ReferenceOAProfiles{})
}
func NewWithProfiles(manifestPath string, profiles ReferenceOAProfiles) (*Server, error) {
	data, err := os.ReadFile(manifestPath)
	if err != nil {
		return nil, fmt.Errorf("read suite manifest: %w", err)
	}
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	decoder.DisallowUnknownFields()
	var value suite
	if err := decoder.Decode(&value); err != nil {
		return nil, fmt.Errorf("decode suite manifest: %w", err)
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return nil, fmt.Errorf("suite manifest contains trailing JSON")
	}
	if value.SchemaVersion != "1" || value.SuiteID == "" || value.TenantID == "" {
		return nil, fmt.Errorf("suite manifest identity is invalid")
	}
	enabled := map[string]bool{}
	for _, app := range value.Applications {
		enabled[app.ID] = app.Enabled
	}
	if profiles.ProductionPersonnel != "" && (profiles.ProductionPersonnel != "reference-oa-production-personnel-v1" || !enabled["project-workspace"] || !enabled["people-groups"]) {
		return nil, fmt.Errorf("production personnel profile requires matching Project and People selection")
	}
	if profiles.Bonus != "" && (profiles.Bonus != "reference-oa-bonus-v2" && profiles.Bonus != "reference-oa-bonus-v3" || !enabled["bonus-distribution"]) {
		return nil, fmt.Errorf("bonus profile requires matching Bonus selection")
	}
	if profiles.Bonus == "reference-oa-bonus-v3" && profiles.ProductionPersonnel == "" {
		return nil, fmt.Errorf("professional Bonus profile requires explicit personnel profile")
	}
	if profiles.ProductionStage != "" && (profiles.ProductionStage != "reference-oa-stage-materials-v1" || !enabled["production-operations"] || !enabled["evidence-service"] || !enabled["project-workspace"] || !enabled["people-groups"]) {
		return nil, fmt.Errorf("production stage profile requires matching Production, Evidence, Project and People selection")
	}
	if profiles.OMSOperatingPartyID != "" && !canonicalUUIDPattern.MatchString(profiles.OMSOperatingPartyID) {
		return nil, fmt.Errorf("OMS operating Party ID must be a canonical lowercase UUID")
	}
	for _, app := range value.Applications {
		if err := app.validateEntry(); err != nil {
			return nil, err
		}
		if app.WorkItemProjection == nil {
			if app.MetricProjection == nil {
				continue
			}
		} else {
			projection := app.WorkItemProjection
			if app.ID == "identity-access" || app.ID == "unified-workbench" || projection.SchemaVersion != "1" || !strings.HasPrefix(projection.Path, "/api/") || strings.Contains(projection.Path, "?") || strings.TrimSpace(projection.Action) == "" || !app.hasEntry() {
				return nil, fmt.Errorf("application %q work item projection is invalid", app.ID)
			}
		}
		if app.MetricProjection != nil {
			projection := app.MetricProjection
			if app.ID == "identity-access" || app.ID == "unified-workbench" || projection.SchemaVersion != "1" || !strings.HasPrefix(projection.Path, "/api/") || strings.Contains(projection.Path, "?") || strings.TrimSpace(projection.Action) == "" || !app.hasEntry() {
				return nil, fmt.Errorf("application %q metric projection is invalid", app.ID)
			}
		}
	}
	page, err := template.New("workbench").Funcs(template.FuncMap{
		"appTitle":       func(id string) string { return presentationFor(id).Title },
		"appDescription": func(id string) string { return presentationFor(id).Description },
		"appGlyph":       func(id string) string { return presentationFor(id).Glyph },
		"appSection":     func(id string) string { return presentationFor(id).Section },
		"dict": func(values ...any) (map[string]any, error) {
			if len(values)%2 != 0 {
				return nil, fmt.Errorf("dict expects key-value pairs")
			}
			result := make(map[string]any, len(values)/2)
			for index := 0; index < len(values); index += 2 {
				key, ok := values[index].(string)
				if !ok {
					return nil, fmt.Errorf("dict key must be a string")
				}
				result[key] = values[index+1]
			}
			return result, nil
		},
	}).Parse(pageHTML + businessViewsHTML + projectDetailPanelsHTML + referenceOAP0WorkspacesHTML + referenceOAInteractiveWorkspacesHTML + referenceOAInitiationWorkspaceHTML + referenceOARealProjectsHTML + referenceOMSDemoHTML + omsPhase1HTML)
	if err != nil {
		return nil, err
	}
	return &Server{suite: value, page: page, profiles: profiles}, nil
}
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Security-Policy", "default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; frame-src 'self' blob:; connect-src 'self'; form-action 'self'; frame-ancestors 'none'")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	switch r.URL.Path {
	case "/health/live", "/health/ready":
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"status":"ready"}`))
	case "/":
		s.home(w, r)
	case "/assets/workbench.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(workbenchScript))
	case "/assets/reference-oa-initiation-runtime.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAInitiationRuntimeJS))
	case "/assets/reference-oa-project-directory.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAProjectDirectoryJS))
	case "/assets/reference-oa-bidding-runtime.js":
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOABiddingRuntimeJS))
	case "/assets/reference-oa-react-bidding.js":
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAReactBiddingJS))
	case "/assets/reference-oa-react-bidding.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAReactBiddingCSS))
	case "/assets/reference-oa-architecture-lens.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAArchitectureLensJS))
	case "/assets/reference-oa-business-runtime.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOABusinessRuntimeJS))
	case "/assets/reference-oa-login.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOALoginCSS))
	case "/assets/reference-oa-login.js":
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOALoginJS))
	case "/assets/reference-oa-workspace.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAWorkspaceCSS))
	case "/assets/reference-oa-admin.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOAAdminCSS))
	case "/assets/reference-oa-business.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOABusinessCSS))
	case "/assets/reference-oa-detail.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOADetailCSS))
	case "/assets/reference-oms-demo.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(referenceOMSDemoCSS))
	case "/assets/reference-oms-demo.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(referenceOMSDemoJS))
	case "/assets/oms-phase1.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write([]byte(omsPhase1CSS))
	case "/assets/oms-phase1.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(omsPhase1JS))
	case "/assets/oms-phase1-pagination.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		_, _ = w.Write([]byte(omsPhase1PaginationJS))
	case "/assets/jinghong-logo.webp":
		logo, err := base64.StdEncoding.DecodeString(strings.TrimSpace(jinghongLogoBase64))
		if err != nil {
			http.Error(w, "品牌资源不可用", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "image/webp")
		w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		_, _ = w.Write(logo)
	default:
		http.NotFound(w, r)
	}
}
func (s *Server) home(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	subject := strings.TrimSpace(r.Header.Get("X-OMS-Subject-ID"))
	demoPreview := subject == "" && r.URL.Query().Get("preview") == "oa"
	requestedView := strings.TrimSpace(r.URL.Query().Get("view"))
	omsPhase1 := requestedView == "oms-v1" || (requestedView == "" && !demoPreview)
	legacyWorkspace := requestedView == "legacy" || (requestedView == "" && demoPreview)
	apps := make([]application, 0)
	businessApps := make([]application, 0)
	sources := make([]application, 0)
	metricSources := make([]application, 0)
	iamRoute := ""
	for _, app := range s.suite.Applications {
		// Every selected native application needs its configured route, even
		// when hidden from navigation. Selection does not grant any capability.
		// An allowlist here silently broke newly assembled original OA forms.
		if app.Enabled && app.hasEntry() {
			businessApps = append(businessApps, app)
		}
		if app.Enabled && app.ID == "identity-access" {
			iamRoute = app.RoutePrefix
		}
		if app.Enabled && app.hasEntry() && (app.ShowInWorkbench == nil || *app.ShowInWorkbench) {
			apps = append(apps, app)
		}
		if app.Enabled && app.WorkItemProjection != nil && app.WorkItemProjection.SchemaVersion == "1" && strings.HasPrefix(app.WorkItemProjection.Path, "/api/") {
			sources = append(sources, app)
		}
		if app.Enabled && app.MetricProjection != nil && app.MetricProjection.SchemaVersion == "1" && strings.HasPrefix(app.MetricProjection.Path, "/api/") {
			metricSources = append(metricSources, app)
		}
	}
	displayName := r.Header.Get("X-OMS-Display-Name")
	administrator := r.Header.Get("X-OMS-Administrator") == "true"
	if demoPreview {
		subject = "00000000-0000-4000-8000-000000000001"
		displayName = "OA 演示用户"
		administrator = true
		// Preview is deliberately detached from protected projections. It proves
		// the reference UI and local interactions without turning demo data into
		// an IAM bypass or making requests with a fabricated actor.
		sources = nil
		metricSources = nil
	}
	returnTo := strings.TrimSpace(r.URL.Query().Get("return_to"))
	if returnTo == "" {
		switch requestedView {
		case "legacy":
			returnTo = "/workbench/?view=legacy"
		case "oms-reference":
			returnTo = "/workbench/?view=oms-reference"
		default:
			returnTo = "/workbench/?view=oms-v1"
		}
	}
	data := pageData{SuiteID: s.suite.SuiteID, Authenticated: subject != "", DemoPreview: demoPreview, OMSPhase1: omsPhase1, LegacyWorkspace: legacyWorkspace, DisplayName: displayName, Administrator: administrator, CSRFToken: r.Header.Get("X-OMS-CSRF-Token"), ReturnTo: returnTo, Applications: apps, BusinessApplications: businessApps, SubjectID: subject, WorkSources: sources, MetricSources: metricSources, TenantID: s.suite.TenantID, IAMRoutePrefix: iamRoute}
	if !demoPreview {
		data.ProductionPersonnelProfile = s.profiles.ProductionPersonnel
		data.BonusProfile = s.profiles.Bonus
		data.ProductionStageProfile = s.profiles.ProductionStage
		data.OMSOperatingPartyID = s.profiles.OMSOperatingPartyID
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := s.page.Execute(w, data); err != nil {
		http.Error(w, "无法显示工作台", 500)
	}
}

